args.CodeContent:
import json
import os

SOL_PATH = '/workspace/output/solution.json'

def load_solution():
    if os.path.exists(SOL_PATH):
        try:
            with open(SOL_PATH, 'r') as f:
                return json.load(f)
        except Exception:
            pass
    return {"sequence": []}

def save_solution(data):
    # Sort sequence by video and then by t_start
    seq = data.get("sequence", [])
    seq.sort(key=lambda x: (x["video"], x["t_start"]))
    data["sequence"] = seq
    with open(SOL_PATH, 'w') as f:
        json.dump(data, f, indent=2)
    print(f"Updated solution.json with {len(seq)} entries.")

def set_video_entries(vid, entries):
    data = load_solution()
    # Remove existing entries for this video
    seq = [x for x in data.get("sequence", []) if x["video"] != vid]
    seq.extend(entries)
    data["sequence"] = seq
    save_solution(data)

if __name__ == '__main__':
    pass

